/**
 * IncidentContext
 *
 * 事件的完整唯讀快照：5、6、7 讀取事件的唯一入口。
 *
 * description 與使用者的訊息可能含個資；送進 LLM 或寫進 log 之前要先去識別化（ADR-0009）。
 */
export type IncidentContext = {
    /**
     * Incident Id
     */
    incident_id: string;
    /**
     * Title
     */
    title: string;
    /**
     * Description
     */
    description: string;
    /**
     * Status
     */
    status: 'open' | 'completed';
    /**
     * Destination
     */
    destination?: string | null;
    /**
     * Occurred At
     */
    occurred_at?: string | null;
    /**
     * Incident Type Code
     */
    incident_type_code?: string | null;
    /**
     * Incident Type Name
     */
    incident_type_name?: string | null;
    /**
     * Follow Up Questions
     *
     * 事件類型預設的追問問題；類型未定時為空
     */
    follow_up_questions?: Array<string>;
    policy: PolicySummary;
    /**
     * Clauses
     */
    clauses?: Array<ClauseView>;
    /**
     * Facts
     */
    facts?: Array<FactView>;
    /**
     * Todos
     */
    todos?: Array<TodoView>;
    /**
     * Documents
     */
    documents?: Array<DocumentView>;
    /**
     * Messages
     */
    messages?: Array<MessageView>;
    /**
     * Event Types
     *
     * 全部事故類型；類型還沒判斷出來時 5 號靠它問
     */
    event_types?: Array<EventTypeView>;
    /**
     * Common Fields
     *
     * 每個事故類型共用的必問欄位（日期、地點）
     */
    common_fields?: Array<FieldView>;
    /**
     * Major Notices
     *
     * 重大注意事項，最多 4 條，平台算好；{start_date}、{end_date} 已帶入保單的日期
     */
    major_notices?: Array<string>;
    /**
     * Covered
     *
     * v2.13（ADR-0029）：事件在保障內。有條款結論、但沒有任何一項是 applicable（含全是 insufficient）就是 False（不符保障的事件）；還沒有結論時是 True。平台推導，5 號不用回報。False 的事件對 6、7 號當作不存在
     */
    covered?: boolean;
};

