/**
 * TodoView
 */
export type TodoView = {
    /**
     * Id
     */
    id: string;
    /**
     * Incident Id
     *
     * v2.13：這項待辦屬於哪個事件；共同文件（ADR-0029）不屬於任何事件，是 None
     */
    incident_id?: string | null;
    /**
     * Template Id
     */
    template_id?: string | null;
    /**
     * Phase
     */
    phase: 'on_site' | 'after_return';
    /**
     * Title
     */
    title: string;
    /**
     * Note
     */
    note?: string | null;
    /**
     * Is Done
     */
    is_done?: boolean;
    /**
     * Status
     */
    status?: 'pending' | 'done' | 'not_applicable';
    /**
     * Done By
     */
    done_by?: 'user' | 'agent' | null;
    /**
     * Sort Order
     */
    sort_order?: number;
    /**
     * Scope
     *
     * policy：整個行程共用的待辦（理賠申請書 D10），不屬於任何事件
     */
    scope?: 'incident' | 'policy';
    /**
     * Document Code
     *
     * 文件代碼（D01…），6 號用它對待辦，不用猜標題
     */
    document_code?: string | null;
    /**
     * Requires Upload
     */
    requires_upload?: boolean;
    /**
     * Keywords
     */
    keywords?: Array<string>;
    /**
     * Notes
     */
    notes?: Array<string>;
    /**
     * Wait Note
     */
    wait_note?: string | null;
    /**
     * Without Document
     *
     * 需上傳的待辦，使用者自行勾選而沒有附文件（規格 v3.4 標「未附文件」）
     */
    without_document?: boolean;
    /**
     * Condition
     *
     * 這份文件的產生條件（field/equals 或 fact），5 號用它判斷修正後還適不適用（2.7.0）
     */
    condition?: {
        [key: string]: unknown;
    } | null;
    /**
     * Is New
     *
     * 狀況更新後才新增或又適用的待辦，畫面標「新增」；勾選後清除（規格 4.5 R5，2.7.0）
     */
    is_new?: boolean;
    /**
     * Applicable
     *
     * v2.4：依最新狀況適不適用（5 號回報，#232）；只是註記，不改 status 與已上傳的文件。false 的待辦對 6、7 號當作不存在（平台交給它們的 todos 已經濾掉），5 號看得到、可以改回
     */
    applicable?: boolean;
};

